<?php $titulo='Alertas e eventos'; $modulo='alertas'; ?>
<div class="mb-3"><h4 class="mb-1">Alertas do sistema</h4><p class="text-muted mb-0">Atualizados a cada minuto. Reconhecer registra quem assumiu o evento; resolver encerra alertas e eventos observados.</p></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Severidade</th><th>Evento</th><th>Origem</th><th>Estado</th><th>Atualizado</th><th></th></tr></thead><tbody><?php foreach($alertas as $a):?><tr><td><span class="badge bg-<?=($a['severidade']==='critico'?'danger':($a['severidade']==='aviso'?'warning':'info'))?>"><?=h($a['severidade'])?></span></td><td><strong><?=h($a['titulo'])?></strong><div class="small text-muted"><?=h($a['mensagem'])?></div></td><td><?=h($a['origem'])?></td><td><?=h($a['estado'])?></td><td><?=h($a['atualizado_em'])?></td><td><div class="d-flex gap-1"><?php if($a['estado']==='aberto'):?><form method="post" action="/alertas/<?=h($a['id'])?>/reconhecer"><?=csrf_field()?><button class="btn btn-sm btn-outline-primary">Reconhecer</button></form><?php endif;?><?php if($a['estado']!=='resolvido'):?><form method="post" action="/alertas/<?=h($a['id'])?>/resolver"><?=csrf_field()?><button class="btn btn-sm btn-outline-success">Resolver</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$alertas):?><tr><td colspan="6" class="text-center text-muted py-4">Sem alertas registrados.</td></tr><?php endif;?></tbody></table></div></div>
